results.js:
const bar = morse.el('div', { id: 'morse-progress-bar' });
document.body.appendChild(bar);
const update = () => {
  const doc = document.documentElement;
  const max = doc.scrollHeight - doc.clientHeight;
  const pct = max > 0 ? (doc.scrollTop / max) * 100 : 0;
  bar.style.width = pct + '%';
};
morse.on(window, 'scroll', update);
morse.on(window, 'resize', update);
update();

