results.js:
morse.every(100, () => {
  const a = document.querySelector('article');
  if (!a) return;
  const r = a.getBoundingClientRect();
  const total = a.offsetHeight - window.innerHeight;
  const done = Math.min(Math.max(-r.top / (total || 1), 0), 1);
  document.documentElement.style.setProperty('--morse-read', (done * 100) + '%');
});

