results.js:
morse.watch('body > div.mn > h1', h1 => {
  if (h1.querySelector('.morse-csv')) return;
  h1.appendChild(morse.el('button', {
    class: 'morse-csv',
    text: 'Export CSV',
    on: { click: () => {
      const rows = [...document.querySelectorAll('div.tbl table tr')];
      const csv = rows.map(tr =>
        [...tr.children].map(c => '"' + c.textContent.trim().replace(/"/g, '""') + '"').join(',')
      ).join('\n');
      const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
      const a = document.createElement('a');
      a.href = url;
      a.download = 'orders.csv';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      morse.toast('Exported ' + Math.max(0, rows.length - 1) + ' orders');
    } }
  }));
});

