morse.watch('div.tbl > h3', h3 => {
  if (h3.parentElement.querySelector('#morse-csv-btn')) return;
  const btn = morse.el('button', {
    id: 'morse-csv-btn',
    type: 'button',
    text: 'Export CSV',
    on: { click: () => {
      const table = h3.parentElement.querySelector('table');
      if (!table) return;
      const rows = [...table.querySelectorAll('tr')].map(tr =>
        [...tr.children].map(c => {
          const v = c.textContent.trim().replace(/"/g, '""');
          return /[",\n]/.test(v) ? `"${v}"` : v;
        }).join(',')
      );
      const blob = new Blob([rows.join('\n')], { type: 'text/csv' });
      const a = morse.el('a', { href: URL.createObjectURL(blob), download: 'orders.csv' });
      document.body.appendChild(a);
      a.click();
      a.remove();
      morse.toast('Exported orders.csv');
    } }
  });
  h3.parentElement.insertBefore(btn, h3.nextSibling);
});

