results.js:
morse.watch('th.am', th => {
  morse.on(th, 'click', () => {
    const dir = th.dataset.dir === 'asc' ? 'desc' : 'asc';
    th.dataset.dir = dir;
    const idx = th.cellIndex;
    const tbody = th.closest('table').tBodies[0];
    const num = r => parseFloat((r.cells[idx]?.textContent || '').replace(/[^0-9.\-]/g, '')) || 0;
    const rows = Array.from(tbody.rows).sort((a, b) =>
      dir === 'asc' ? num(a) - num(b) : num(b) - num(a));
    rows.forEach(r => tbody.appendChild(r));
  });
});

results.css:
th.am { cursor: pointer; user-select: none; }
