results.js:
morse.watch("div.tbl table thead th.am", th => {
  if (th.dataset.wired) return;
  th.dataset.wired = "1";
  morse.on(th, "click", () => {
    const table = th.closest("table");
    const tbody = table.querySelector("tbody");
    const idx = th.cellIndex;
    const next = th.dataset.sort === "desc" ? "asc" : "desc";
    const rows = Array.from(tbody.querySelectorAll("tr"));
    const num = s => parseFloat(String(s).replace(/[^0-9.\-]/g, "")) || 0;
    rows.sort((a, b) => {
      const d = num(a.cells[idx].textContent) - num(b.cells[idx].textContent);
      return next === "asc" ? d : -d;
    });
    rows.forEach(r => tbody.appendChild(r));
    table.querySelectorAll("th").forEach(h => delete h.dataset.sort);
    th.dataset.sort = next;
  });
});

