morse.watch('div.tbl .sc table', t => {
  const val = morse.el('td', { class: 'am', text: '' });
  const foot = morse.el('tfoot', {},
    morse.el('tr', {},
      morse.el('td', { colspan: '4', text: 'Total' }),
      val
    )
  );
  t.appendChild(foot);
  const update = () => {
