results.js:
const ensureTotal = t => {
  let f = t.querySelector('tfoot.morse-total');
  if (!f) {
    f = morse.el('tfoot', { class: 'morse-total' },
      morse.el('tr', {},
        morse.el('td', { colspan: '4', text: 'Total' }),
        morse.el('td', { class: 'am' })));
    t.appendChild(f);
  }
  const sum = [...t.querySelectorAll('tbody td.am')]
    .reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0);
  f.querySelector('td.am').textContent =
    sum.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};
morse.watch('.tbl .sc table', ensureTotal);
morse.every(1000, () => document.querySelectorAll('.tbl .sc table').forEach(ensureTotal));

