results.js:
morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('[data-morse-date]')) return;
  const btn = morse.el('button', {
    title: "Insert today's date",
    'data-morse-date': '',
    text: 'Date',
    on: {
      click: () => {
        const d = new Date();
        const s = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        const sel = window.getSelection();
        const editor = document.querySelector('div[role="textbox"]');
        if (editor) editor.focus();
        if (sel && sel.rangeCount) {
          const range = sel.getRangeAt(0);
          range.deleteContents();
          range.insertNode(document.createTextNode(s));
          range.collapse(false);
        } else if (editor) {
          editor.append(s);
        }
        morse.toast('Inserted ' + s);
      }
    }
  });
  bar.append(btn);
});

