morse.watch('div[role="textbox"]', el => {
  const out = morse.el('div', { class: 'morse-wc' });
  el.parentElement.appendChild(out);
  const update = () => {
    const n = el.textContent.trim().split(/\s+/).filter(Boolean).length;
    out.textContent = n + (n === 1 ? ' word' : ' words');
  };
  morse.on(el, 'input', update);
  morse.every(1000, update);
  update();
});

morse.watch('div[role="textbox"]', el => {
  if (el.nextElementSibling && el.nextElementSibling.hasAttribute('data-morse-wc')) return;
  const counter = morse.el('div', { class: 'morse-wc', 'data-morse-wc': '' });
  el.insertAdjacentElement('afterend', counter);
  const update = () => {
    const n = (el.innerText.match(/\S+/g) || []).length;
    counter.textContent = n + (n === 1 ? ' word' : ' words');
  };
  morse.on(el, 'input', update);
  update();
});

