morse.watch('header[role="banner"] > div:last-child', host => {
  if (host.querySelector('.morse-copy-md')) return;
  const btn = morse.el('button', {
    class: 'morse-copy-md',
    text: 'Copy as Markdown',
    on: { click: () => {
      const lines = [];
      document.querySelectorAll('section[aria-label="Conversation"] [data-role]').forEach(m => {
        const who = m.dataset.role === 'user' ? 'You' : 'Parley';
        lines.push('**' + who + ':**\n\n' + m.innerText.trim());
      });
      const md = lines.join('\n\n---\n\n');
      navigator.clipboard.writeText(md).then(
        () => morse.toast('Conversation copied as Markdown'),
        () => morse.toast('Copy failed')
      );
    } }
  });
  host.prepend(btn);
});

