morse.watch('[data-testid="player-controls"]', el => {
  if (el.querySelector('.sleep-timer')) return;
  const btn = morse.el('button', {
    class: 'sleep-timer',
    'aria-label': 'Sleep timer',
    text: '☾',
    on: {
      click: () => {
        const mins = parseInt(prompt('Sleep after how many minutes?', '30'), 10);
        if (!mins || mins <= 0) return;
        morse.toast(`Sleep timer set for ${mins} min`);
        setTimeout(() => {
          const pause = document.querySelector('button[data-testid="play-pause"]');
          if (pause && pause.getAttribute('aria-label') === 'Pause') pause.click();
          morse.toast('Sleep timer: playback paused');
        }, mins * 60 * 1000);
      }
    }
  });
  el.querySelector('.btns')?.appendChild(btn);
});

morse.watch('[data-testid="player-controls"] .btns', btns => {
  if (btns.querySelector('[data-sleep]')) return;
  const steps = [0, 15, 30, 45, 60];
  let mins = 0, timer = null;
  const btn = morse.el('button', { 'aria-label': 'Sleep timer', 'data-sleep': '', text: '☾', title: 'Sleep timer' });
  const pauseNow = () => {
    const pp = document.querySelector('button[data-testid="play-pause"]');
    if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
    mins = 0; timer = null; btn.textContent = '☾';
    morse.toast('Sleep timer: playback paused');
  };
  btn.addEventListener('click', () => {
    mins = steps[(steps.indexOf(mins) + 1) % steps.length];
    clearTimeout(timer); timer = null;
    if (mins) {
      timer = setTimeout(pauseNow, mins * 60000);
      btn.textContent = '☾' + mins;
      morse.toast('Sleep timer: ' + mins + ' min');
    } else {
      btn.textContent = '☾';
      morse.toast('Sleep timer off');
    }
  });
  btns.append(btn);
});

morse.watch('[data-testid="player-controls"]', el => {
