morse.watch('div.tbl > div.sc', sc => {
  if (sc.querySelector('input.morse-search')) return;
  const input = morse.el('input', {
    class: 'morse-search',
    type: 'search',
    placeholder: 'Search orders…',
    'aria-label': 'Search orders'
  });
  sc.parentElement.insertBefore(input, sc);
  const rows = () => sc.querySelectorAll('tbody tr');
  input.addEventListener('input', () => {
    const q = input.value.trim().toLowerCase();
    rows().forEach(tr => {
      const match = !q || tr.textContent.toLowerCase().includes(q);
      tr.classList.toggle('morse-hidden', !match);
    });
  });
});

