morse.on(document, "keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  if (e.key !== "j" && e.key !== "k") return;
  const rows = [...document.querySelectorAll('section[aria-label="Message\\ list"] [role="option"][data-i]')];
  if (!rows.length) return;
  let idx = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  idx = e.key === "j" ? Math.min(idx + 1, rows.length - 1) : Math.max(idx < 0 ? 0 : idx - 1, 0);
  const next = rows[idx];
  if (!next) return;
  e.preventDefault();
  rows.forEach(r => r.setAttribute("aria-selected", r === next ? "true" : "false"));
  next.click();
  next.scrollIntoView({ block: "nearest" });
});

morse.watch('div.r9[data-i]', el => {
  if (el.dataset.morseKeys) return;
  el.dataset.morseKeys = '1';
});

function morseMove(delta) {
  const rows = [...document.querySelectorAll('div.lst div.r9[data-i]')];
  if (!rows.length) return;
  let idx = rows.findIndex(r => r.getAttribute('aria-selected') === 'true');
  const next = rows[Math.min(rows.length - 1, Math.max(0, idx + delta))];
  if (!next || next === rows[idx]) return;
  next.click();
  next.scrollIntoView({ block: 'nearest' });
  next.focus?.();
}

morse.on(document, 'keydown', e => {
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === 'j') { e.preventDefault(); morseMove(1); }
  else if (e.key === 'k') { e.preventDefault(); morseMove(-1); }
});

morse.toast('j / k: next / previous email');

morse.on(document, "keydown", e => {
  if (e.target.matches("input, textarea, [contenteditable]") || e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key !== "j" && e.key !== "k") return;
  const rows = [...document.querySelectorAll('[role="option"][data-i]')];
  if (!rows.length) return;
  const cur = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  const next = e.key === "j" ? Math.min(cur + 1, rows.length - 1) : Math.max(cur < 0 ? 0 : cur - 1, 0);
  const target = rows[next];
  rows.forEach(r => r.setAttribute("aria-selected", r === target ? "true" : "false"));
  target.scrollIntoView({ block: "nearest" });
  target.click();
});

