  morse.on(input, 'input', run);
  run();
});

morse.watch('section[aria-label="Message\\ list"] div.r9[role="option"]', el => {
  const apply = () => {
    const q = (document.querySelector('input[aria-label="Search\\ mail"]')?.value || '').trim().toLowerCase();
