results.js:
const KEY = "sidebarCollapsed";
const nav = () => document.querySelector('nav[aria-label="Chat\\ history"]');
let collapsed = !!morse.store.get(KEY);

function apply() {
  const n = nav();
  if (n) n.classList.toggle("morse-collapsed", collapsed);
  const b = document.getElementById("morse-sidebar-toggle");
  if (b) {
    b.textContent = collapsed ? "»" : "«";
    b.setAttribute("aria-label", collapsed ? "Expand sidebar" : "Collapse sidebar");
    b.setAttribute("aria-expanded", String(!collapsed));
  }
}

morse.watch("body", () => {
  if (document.getElementById("morse-sidebar-toggle")) return;
  const btn = morse.el("button", {
    id: "morse-sidebar-toggle",
    type: "button",
    on: {
      click: () => {
        collapsed = !collapsed;
        morse.store.set(KEY, collapsed);
        apply();
      }
    }
  }, "«");
  document.body.appendChild(btn);
  apply();
});

morse.every(500, apply);

